import{_ as a,o as e,c as o,ai as d}from"./chunks/framework.scx6l_IK.js";const s=JSON.parse('{"title":"中道","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-中道.md","filePath":"50-概念资料/dict-中道.md","lastUpdated":1778155802000}'),l={name:"50-概念资料/dict-中道.md"};function r(i,t,u,h,c,q){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="中道" tabindex="-1">中道 <a class="header-anchor" href="#中道" aria-label="Permalink to &quot;中道&quot;">​</a></h1><blockquote><p>传统：通用/佛家 | 道家对应：守中 | 儒家对应：中庸</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>中道是佛教（尤其是大乘佛教）的核心方法论——不走极端，不走两边，在&quot;有&quot;和&quot;空&quot;、&quot;做&quot;和&quot;不做&quot;之间找到智慧的平衡。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;因上精进，果上随缘就是中观。&quot;——了空居士对中道最精炼的表达</p></blockquote><blockquote><p>&quot;不应取法，不应取非法——不能执着于方法，也不能执着于&#39;一切都是空的&#39;。吃药好了就不吃了，病没好也不能不吃。&quot;</p></blockquote><blockquote><p>&quot;守中不是停在中间不动，是不走极端。就像开车，要不断微调方向才能保持在车道中间。&quot;</p></blockquote><blockquote><p>&quot;多言数穷，不如守中——话说多了反而说不清楚，不如保持内心清净，该说就说，不该说就不说。&quot;</p></blockquote><h2 id="中道的日常表现" tabindex="-1">中道的日常表现 <a class="header-anchor" href="#中道的日常表现" aria-label="Permalink to &quot;中道的日常表现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>左极端</th><th>中道</th><th>右极端</th></tr></thead><tbody><tr><td>物质</td><td>极度节俭（吝啬）</td><td>够用就好，取之有道</td><td>挥霍无度（浪费）</td></tr><tr><td>修行</td><td>过度苦修</td><td>自然务实，中正安舒</td><td>放纵享乐</td></tr><tr><td>情绪</td><td>压抑情绪</td><td>觉察情绪，转化情绪</td><td>发泄情绪</td></tr><tr><td>布施</td><td>一毛不拔</td><td>随缘布施，不攀缘</td><td>什么都不留地布施</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-不二">不二</a> — 中道是不二的实践方法</li><li><a href="/50-概念资料/dict-圆融中和">圆融中和</a> — 中道在日常生活中的体现</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-圆融中和">圆融中和</a> — 中道的生活化表达</li><li><a href="/10-核心模型/model-对法不执">对法不执</a> — 不执于两边</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>不急于下判断，先看看有没有第三种可能</li><li>做事做到&quot;差不多&quot;——刚好就是最合适的度</li><li>不走极端：该努力时努力，该休息时休息</li></ul>',17)])])}const b=a(l,[["render",r]]);export{s as __pageData,b as default};
